  "home.meta.h1": { nb: "Søk. Sammenlign. Reis smartere.", en: "Search. Compare. Travel smarter.", sv: "Sök. Jämför. Res smartare.", da: "Søg. Sammenlign. Rejs smartere.", de: "Suchen. Vergleichen. Smarter reisen." },
  "home.meta.sub": { nb: "Priser fra flyselskaper, hoteller og reisebyråer i ett søk – bestillingen fullføres alltid hos leverandøren.", en: "Prices from airlines, hotels and travel agencies in one search – booking is always completed with the provider.", sv: "Priser från flygbolag, hotell och resebyråer i en sökning – bokningen slutförs alltid hos leverantören.", da: "Priser fra flyselskaber, hoteller og rejsebureauer i én søgning – bestillingen gennemføres altid hos leverandøren.", de: "Preise von Airlines, Hotels und Reisebüros in einer Suche – gebucht wird immer beim Anbieter." },
  "home.how.title": { nb: "Slik fungerer HelloSky", en: "How HelloSky works", sv: "Så fungerar HelloSky", da: "Sådan virker HelloSky", de: "So funktioniert HelloSky" },
  "home.how.1.title": { nb: "Søk", en: "Search", sv: "Sök", da: "Søg", de: "Suchen" },
  "home.how.1.body": { nb: "Ett søk henter priser fra flyselskaper og reisebyråer via våre partnere.", en: "One search fetches prices from airlines and travel agencies through our partners.", sv: "En sökning hämtar priser från flygbolag och resebyråer via våra partner.", da: "Én søgning henter priser fra flyselskaber og rejsebureauer via vores partnere.", de: "Eine Suche holt Preise von Airlines und Reisebüros über unsere Partner." },
  "home.how.2.title": { nb: "Sammenlign", en: "Compare", sv: "Jämför", da: "Sammenlign", de: "Vergleichen" },
  "home.how.2.body": { nb: "Filtrer på pris, reisetid, stopp og selger. Vi viser alltid hvem som selger billetten.", en: "Filter by price, travel time, stops and seller. We always show who sells the ticket.", sv: "Filtrera på pris, restid, stopp och säljare. Vi visar alltid vem som säljer biljetten.", da: "Filtrér på pris, rejsetid, stop og sælger. Vi viser altid, hvem der sælger billetten.", de: "Nach Preis, Reisezeit, Stopps und Verkäufer filtern. Wir zeigen immer, wer das Ticket verkauft." },
  "home.how.3.title": { nb: "Bestill hos leverandøren", en: "Book with the provider", sv: "Boka hos leverantören", da: "Bestil hos leverandøren", de: "Beim Anbieter buchen" },
  "home.how.3.body": { nb: "Du fullfører bestillingen direkte hos flyselskapet eller reisebyrået. HelloSky tar ikke betaling.", en: "You complete the booking directly with the airline or travel agency. HelloSky takes no payment.", sv: "Du slutför bokningen direkt hos flygbolaget eller resebyrån. HelloSky tar ingen betalning.", da: "Du gennemfører bestillingen direkte hos flyselskabet eller rejsebureauet. HelloSky tager ingen betaling.", de: "Sie buchen direkt bei der Airline oder dem Reisebüro. HelloSky nimmt keine Zahlung an." },
  "home.metatrust.1.title": { nb: "Ingen skjulte gebyrer", en: "No hidden fees", sv: "Inga dolda avgifter", da: "Ingen skjulte gebyrer", de: "Keine versteckten Gebühren" },
  "home.metatrust.1.body": { nb: "Prisen du ser er prisen leverandøren oppgir. Vi legger ikke på noe.", en: "The price you see is the price the provider states. We add nothing.", sv: "Priset du ser är priset leverantören anger. Vi lägger inte på något.", da: "Prisen du ser, er prisen leverandøren oplyser. Vi lægger intet på.", de: "Der angezeigte Preis ist der Preis des Anbieters. Wir schlagen nichts auf." },
  "home.metatrust.2.title": { nb: "Vi viser alltid selgeren", en: "We always show the seller", sv: "Vi visar alltid säljaren", da: "Vi viser altid sælgeren", de: "Wir zeigen immer den Verkäufer" },
  "home.metatrust.2.body": { nb: "Flyselskap direkte eller reisebyrå – tydelig merket på hvert resultat.", en: "Airline direct or travel agency – clearly marked on every result.", sv: "Flygbolag direkt eller resebyrå – tydligt märkt på varje resultat.", da: "Flyselskab direkte eller rejsebureau – tydeligt markeret på hvert resultat.", de: "Airline direkt oder Reisebüro – bei jedem Ergebnis klar gekennzeichnet." },
  "home.metatrust.3.title": { nb: "Sammenligning fra flere kilder", en: "Comparison from several sources", sv: "Jämförelse från flera källor", da: "Sammenligning fra flere kilder", de: "Vergleich aus mehreren Quellen" },
  "home.metatrust.3.body": { nb: "Priser via KAYAK-partnernettverket og direkte leverandører.", en: "Prices through the KAYAK partner network and direct providers.", sv: "Priser via KAYAKs partnernätverk och direkta leverantörer.", da: "Priser via KAYAK-partnernetværket og direkte leverandører.", de: "Preise über das KAYAK-Partnernetzwerk und direkte Anbieter." },
