  "sp.team.aria": { nb: "Menneskene bak HelloSky", en: "The people behind HelloSky" },
  "sp.team.kicker": { nb: "Kontakt oss i dag", en: "Contact us today" },
  "sp.team.title": { nb: "Menneskene bak HelloSky", en: "The people behind HelloSky" },
  "sp.team.sub": { nb: "Når du ringer eller skriver til oss, er det oss du får tak i. Vi kjenner rutene, sesongene – og hva som betyr noe underveis. Trykk på WhatsApp-knappen, så åpnes chatten direkte.", en: "When you call or write to us, it is us you reach. We know the routes, the seasons – and what matters along the way. Tap the WhatsApp button to open the chat directly." },
  "sp.team.role.owner": { nb: "Eier og daglig leder", en: "Owner and general manager" },
