  "sp.team.quote.owner": { nb: "Jeg startet HelloSky fordi det å finne riktig billett aldri skulle vært så komplisert.", en: "I started HelloSky because finding the right ticket should never have been this complicated." },
  "sp.team.quote.support": { nb: "Ingen henvendelse er for liten. Vi svarer alltid – også på kveldstid.", en: "No request is too small. We always answer – evenings too." },
